insert into public.players_master
 (cpbl_id,full_name,primary_position,initial_team_id,source_year,source_type,source_license,
  data_confidence,draft_year,draft_round)
select 'draft:'||draft_year::text||':'||team_id||':'||draft_round::text,
 full_name,position,team_id,draft_year,'draft_selection',
 case when draft_year=2025 then '2025 CPBL Draft Results; taisounds.com/news/content/101/198946'
 else '2026 CPBL Draft Results; sportsv.net/articles/127291; cpbl.com.tw' end,
 'draft_result_reported',draft_year,draft_round from picks
on conflict(cpbl_id) do update set full_name=excluded.full_name,
 primary_position=excluded.primary_position,initial_team_id=excluded.initial_team_id,
 draft_year=excluded.draft_year,draft_round=excluded.draft_round;

insert into public.league_players
 (league_id,master_player_id,team_id,roster_status,monthly_salary_ntd,
  fa_service_seasons,batting_rating,pitching_rating,fielding_rating,
  fa_years_verified,salary_verified)
select l.id,p.id,p.initial_team_id,'reserve',0,0,50,50,50,false,false
from public.players_master p cross join public.leagues l
where p.source_type='draft_selection' and p.draft_year in(2025,2026)
on conflict(league_id,master_player_id) do nothing;

update public.leagues set roster_source_status=
 '2024_rebas_game_appearances_plus_2025_2026_draft_selections; missing_2024_nonparticipants_and_contracts'
 where kind in('gm','official');
update public.leagues set is_ready=false,clock_enabled=false where kind='official';